VALUES
    ('en_US', 'LOC_DISTRICT_CSC_TAILORS_QUARTER_NAME', 'Tailors'' Quarter'),
    ('en_US', 'LOC_DISTRICT_CSC_TAILORS_QUARTER_DESCRIPTION', 'A district in your city specializing in textiles.[NEWLINE][NEWLINE]+1 [ICON_Production] Production from each adjacent [ICON_CSC_BASE] Base or [ICON_CSC_SPEC] Specialty Materials resource from this supply chain.[NEWLINE]+1 [ICON_Gold] Gold from each adjacent [ICON_CSC_SALES] Harbor, and +1 [ICON_Production] Production in return.[NEWLINE]+1 [ICON_Gold] Gold from each adjacent [ICON_CSC_SALES] Commercial Hub, Holy Site and Theater Square, and +1 [ICON_Culture] Culture in return.[NEWLINE]+1 [ICON_Production] Production from every 2 adjacent river segments.'),
    ('en_US', 'LOC_BUILDING_CSC_TAILORS_TEXTILE_WORKSHOP_NAME', 'Textile Workshop'),
    ('en_US', 'LOC_BUILDING_CSC_TAILORS_TEXTILE_WORKSHOP_DESCRIPTION', 'A building unique to the Tailors'' Quarter.[NEWLINE][NEWLINE]+1 [ICON_Culture] Culture from each adjacent [ICON_CSC_BASE] Base Materials improvement.[NEWLINE]+1 [ICON_Production] Production and +1 [ICON_Gold] Gold to each adjacent [ICON_CSC_BASE] Base Materials improvement.[NEWLINE]+1 [ICON_Production] Production to each adjacent Lighthouse, and +1 [ICON_Production] Production and +1 [ICON_Gold] Gold to the Textile Workshop in return.[NEWLINE]At Naval Tradition, a Textile Workshop adjacent to an improved [ICON_CSC_BASE] Base Materials resource establishes a Sailmaker in an adjacent Harbor with a Lighthouse.'),
    ('en_US', 'LOC_BUILDING_CSC_TAILORS_SAILMAKER_NAME', 'Sailmaker'),
    ('en_US', 'LOC_BUILDING_CSC_TAILORS_SAILMAKER_DESCRIPTION', 'A Tailors'' Quarter service established by an adjacent Textile Workshop.[NEWLINE][NEWLINE]Provides +20% [ICON_Production] Production toward Renaissance Era or earlier naval units and +1 [ICON_GreatAdmiral] Great Admiral point per turn.'),
    ('en_US', 'LOC_CSC_TAILORS_SAILMAKER_EFFECT', '[NEWLINE][NEWLINE]A Textile Workshop adjacent to an improved [ICON_CSC_BASE] Base Materials resource can establish a Sailmaker here at Naval Tradition. A Sailmaker provides +20% [ICON_Production] Production toward Renaissance Era or earlier naval units and +1 [ICON_GreatAdmiral] Great Admiral point per turn.'),
    ('en_US', 'LOC_CSC_TAILORS_SAILMAKER_CIVIC', '[NEWLINE][NEWLINE]Textile Workshops adjacent to improved [ICON_CSC_BASE] Base Materials resources establish Sailmakers in adjacent Harbors with Lighthouses.'),
    ('en_US', 'LOC_PEDIA_BUILDINGS_PAGE_BUILDING_CSC_TAILORS_TEXTILE_WORKSHOP_CHAPTER_CSCHAIN_TITLE', 'Supply Chains'),
    ('en_US', 'LOC_PEDIA_BUILDINGS_PAGE_BUILDING_CSC_TAILORS_TEXTILE_WORKSHOP_CHAPTER_CSCHAIN_PARA_1', 'The Textile Workshop purchases fibers from nearby improved [ICON_CSC_BASE] Base Materials and turns them into cloth. It pays its suppliers in Production and Gold, while an adjacent Lighthouse buys textiles for maritime use and returns Production and Gold to the workshop.'),
    ('en_US', 'LOC_PEDIA_BUILDINGS_PAGE_BUILDING_CSC_TAILORS_TEXTILE_WORKSHOP_CHAPTER_HISTORY_TITLE', 'Historical Context'),
    ('en_US', 'LOC_PEDIA_BUILDINGS_PAGE_BUILDING_CSC_TAILORS_TEXTILE_WORKSHOP_CHAPTER_HISTORY_PARA_1', 'Textile work tied farms, plantations, workshops, and ports together. Spinning, weaving, dyeing, and sailcloth production turned local fibers into durable goods that could serve households, armies, and long-distance trade.'),
    ('en_US', 'LOC_PEDIA_BUILDINGS_PAGE_BUILDING_LIGHTHOUSE_CHAPTER_CSCHAIN_TITLE', 'Supply Chains'),
    ('en_US', 'LOC_PEDIA_BUILDINGS_PAGE_BUILDING_LIGHTHOUSE_CHAPTER_CSCHAIN_PARA_1', 'An adjacent Textile Workshop supplies a functioning Lighthouse with textiles. At Naval Tradition, that same relationship can establish a Sailmaker service in the Harbor.'),
    ('en_US', 'LOC_PEDIA_BUILDINGS_PAGE_BUILDING_LIGHTHOUSE_CHAPTER_HISTORY_TITLE', 'Historical Context'),
    ('en_US', 'LOC_PEDIA_BUILDINGS_PAGE_BUILDING_LIGHTHOUSE_CHAPTER_HISTORY_PARA_1', 'Ports depended on a web of local crafts. Sailcloth, rope, timber, and repair work kept ships useful between voyages and made maritime traffic a durable part of city life.'),
    ('en_US', 'LOC_PEDIA_BUILDINGS_PAGE_BUILDING_CSC_TAILORS_SAILMAKER_CHAPTER_CSCHAIN_TITLE', 'Supply Chains'),
    ('en_US', 'LOC_PEDIA_BUILDINGS_PAGE_BUILDING_CSC_TAILORS_SAILMAKER_CHAPTER_CSCHAIN_PARA_1', 'The Sailmaker is a Harbor service established by an eligible adjacent Textile Workshop after Naval Tradition. It improves production of Ancient through Renaissance naval melee, ranged, and raider units and provides a Great Admiral point.'),
    ('en_US', 'LOC_PEDIA_BUILDINGS_PAGE_BUILDING_CSC_TAILORS_SAILMAKER_CHAPTER_HISTORY_TITLE', 'Historical Context'),
    ('en_US', 'LOC_PEDIA_BUILDINGS_PAGE_BUILDING_CSC_TAILORS_SAILMAKER_CHAPTER_HISTORY_PARA_1', 'Sailmakers specialized in cutting, stitching, repairing, and storing the heavy cloth that made seafaring practical. Their work was a strategic craft wherever a port depended on wind-driven vessels.');
